ALTER TABLE "survey_group_states" ADD COLUMN "deidentification_decision" jsonb;--> statement-breakpoint
ALTER TABLE "survey_group_states" ADD CONSTRAINT "survey_group_states_confirmed_deidentification_proof_check" CHECK ("survey_group_states"."status" <> 'confirmed' OR ("survey_group_states"."deidentification_decision"->>'status' = 'accepted' AND "survey_group_states"."deidentification_decision"->>'policyVersion' = 'deidentification-v1' AND jsonb_typeof("survey_group_states"."deidentification_decision"->'reasons') = 'array' AND jsonb_array_length("survey_group_states"."deidentification_decision"->'reasons') = 0)) NOT VALID;
